"""Diagram generation from structural store index files.

Reads plain text index files (_inheritance.txt, _imports.txt, _index.txt)
and generates Mermaid diagram source files.
"""
import logging
from pathlib import Path

logger = logging.getLogger(__name__)


class DiagramGenerator:
    """Generate Mermaid diagrams from structural store index files."""

    def generate_all(self, snapshot_path: Path):
        """Generate all diagram types for a snapshot."""
        diagrams_dir = snapshot_path / "diagrams"
        diagrams_dir.mkdir(exist_ok=True)

        self._generate_class_diagram(snapshot_path, diagrams_dir)
        self._generate_inheritance_tree(snapshot_path, diagrams_dir)
        self._generate_dependency_graph(snapshot_path, diagrams_dir)
        self._generate_component_diagram(snapshot_path, diagrams_dir)
        self._generate_pattern_map(snapshot_path, diagrams_dir)

        logger.info(f"Diagrams generated in {diagrams_dir}")

    def _generate_class_diagram(self, snapshot_path: Path, diagrams_dir: Path):
        """Generate UML class diagram from _index.txt + _inheritance.txt."""
        index = self._read_index(snapshot_path)
        inheritance = self._read_inheritance(snapshot_path)

        if not index:
            return

        lines = ["classDiagram"]

        # Group symbols by class
        classes: dict[str, list[dict]] = {}
        for entry in index:
            if entry["kind"] == "class":
                classes.setdefault(entry["name"], [])
            elif entry["scope"] != "-" and entry["scope"] in classes:
                classes.setdefault(entry["scope"], []).append(entry)

        # Emit class definitions
        for class_name, members in sorted(classes.items()):
            lines.append(f"    class {self._sanitize_id(class_name)} {{")
            for m in members:
                vis = self._mermaid_visibility(m.get("name", ""))
                sig = m.get("signature", "-")
                if sig == "-":
                    sig = ""
                if m["kind"] == "method":
                    lines.append(f"        {vis}{m['name']}{sig}")
                elif m["kind"] == "property":
                    lines.append(f"        {vis}{m['name']}")
                elif m["kind"] in ("variable", "constant"):
                    lines.append(f"        {vis}{m['name']}")
            lines.append("    }")

        # Emit inheritance relationships
        for rel in inheritance:
            parent_id = self._sanitize_id(rel["parent"])
            child_id = self._sanitize_id(rel["child"])
            if rel["rel"] == "extends":
                lines.append(f"    {parent_id} <|-- {child_id}")
            elif rel["rel"] == "implements":
                lines.append(f"    {parent_id} <|.. {child_id}")

        if len(lines) > 1:
            self._write_diagram(diagrams_dir / "class-diagram.mmd", "\n".join(lines))

    def _generate_inheritance_tree(self, snapshot_path: Path, diagrams_dir: Path):
        """Generate inheritance tree from _inheritance.txt."""
        inheritance = self._read_inheritance(snapshot_path)
        if not inheritance:
            return

        lines = ["graph TD"]
        seen = set()
        for rel in inheritance:
            parent_id = self._sanitize_id(rel["parent"])
            child_id = self._sanitize_id(rel["child"])
            edge = f"{parent_id} --> {child_id}"
            if edge not in seen:
                lines.append(f"    {edge}")
                seen.add(edge)

        if len(lines) > 1:
            self._write_diagram(diagrams_dir / "inheritance-tree.mmd", "\n".join(lines))

    def _generate_dependency_graph(self, snapshot_path: Path, diagrams_dir: Path):
        """Generate module dependency graph from _imports.txt."""
        imports = self._read_imports(snapshot_path)
        if not imports:
            return

        lines = ["graph LR"]
        seen = set()
        for imp in imports:
            source = self._sanitize_id(imp["file"].replace("/", "_").replace(".", "_"))
            target = self._sanitize_id(imp["module"].replace(".", "_"))
            # Use readable labels
            source_label = imp["file"].split("/")[-1] if "/" in imp["file"] else imp["file"]
            target_label = imp["module"].split(".")[-1] if "." in imp["module"] else imp["module"]
            edge_key = f"{source}->{target}"
            if edge_key not in seen:
                lines.append(f"    {source}[\"{source_label}\"] --> {target}[\"{target_label}\"]")
                seen.add(edge_key)

        if len(lines) > 1:
            self._write_diagram(diagrams_dir / "dependency-graph.mmd", "\n".join(lines))

    def _generate_component_diagram(self, snapshot_path: Path, diagrams_dir: Path):
        """Generate component diagram from _imports.txt grouped by directory."""
        imports = self._read_imports(snapshot_path)
        if not imports:
            return

        # Group files by directory
