        for rel in inheritance:
            parent_id = self._sanitize_id(rel["parent"])
            child_id = self._sanitize_id(rel["child"])
            if rel["rel"] == "extends":
                lines.append(f"    {parent_id} <|-- {child_id}")
            elif rel["rel"] == "implements":
