from abc import ABC, abstractmethod
from typing import Optional
import logging
import yaml
import os

from src.ast.models import StructuralAnalysis

logger = logging.getLogger(__name__)


class AnalysisProvider(ABC):
    """Base class for structural analysis providers.

    Public API is analyze_batch() only. Single-file analysis
    goes through analyze_batch([file]). This ensures we always
    use the efficient batch path — no accidental per-file subprocess spawning.
    """

    @abstractmethod
    def analyze_batch(self, file_paths: list[str]) -> dict[str, StructuralAnalysis]:
        """Analyze multiple files. This is the ONLY public analysis method.
        For single files, call analyze_batch([path]).
        Returns dict of file_path → StructuralAnalysis."""
        pass

    @abstractmethod
    def is_available(self) -> bool:
        """Check if provider binary/service is available."""
        pass

    @property
    @abstractmethod
    def name(self) -> str:
        """Provider name for logging and caching."""
        pass


class ProviderRegistry:
    def __init__(self, config_path: Optional[str] = None):
        self._providers: list[AnalysisProvider] = []
        self._config = self._load_config(config_path)

    def _load_config(self, config_path: Optional[str]) -> dict:
        if config_path and os.path.exists(config_path):
            with open(config_path) as f:
                return yaml.safe_load(f) or {}
        return {
            "providers": {
                "ctags": {"enabled": os.environ.get("AST_CTAGS_ENABLED", "true").lower() == "true"},
                "lsp": {"enabled": os.environ.get("AST_LSP_ENABLED", "false").lower() == "true"},
                "llm": {"enabled": os.environ.get("AST_LLM_ENABLED", "true").lower() == "true"},
            }
        }

    def is_provider_enabled(self, provider_name: str) -> bool:
        providers = self._config.get("providers", {})
        # Default to True for providers not in config (they were explicitly registered)
        return providers.get(provider_name, {}).get("enabled", True)

    def register(self, provider: AnalysisProvider) -> None:
        self._providers.append(provider)
        logger.info(f"Registered analysis provider: {provider.name}")

    def analyze_batch(self, file_paths: list[str]) -> dict[str, StructuralAnalysis]:
        """Analyze files using the first available enabled provider.
        Single entry point for all analysis — batch is the only public API."""
        for provider in self._providers:
            if not self.is_provider_enabled(provider.name):
                continue
            if not provider.is_available():
                logger.warning(f"Provider {provider.name} not available, skipping")
                continue
            try:
                results = provider.analyze_batch(file_paths)
                if results:
                    return results
            except Exception as e:
                logger.error(f"Provider {provider.name} failed: {e}")
                continue
        return {}

"""Diagram builders — read structural store index files and produce DiagramModels.

Each builder reads from the grepable text files (_index.txt, _inheritance.txt, etc.)
and outputs a format-agnostic DiagramModel. Serialisers then convert to Mermaid,
PlantUML, Graphviz, or metamodel format.
"""
import logging
from pathlib import Path
from typing import Optional

from src.ast.diagram_model import DiagramModel, DiagramEntity, DiagramRelationship

logger = logging.getLogger(__name__)


# --- Shared file readers ---
# These parse the tab-separated index files into dicts.
# Used by all builders — one place to maintain the file format contract.

def read_index(snapshot_path: Path) -> list[dict]:
    """Read _index.txt into list of dicts."""
    index_file = snapshot_path / "_index.txt"
    if not index_file.exists():
        return []
    entries = []
    for line in index_file.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or not line.strip():
            continue
        parts = line.split("\t")
        if len(parts) >= 7:
            entries.append({
                "file": parts[0],
                "kind": parts[1],
                "name": parts[2],
                "scope": parts[3],
                "signature": parts[4],
                "line": parts[5],
                "flags": parts[6],
            })
    return entries


def read_inheritance(snapshot_path: Path) -> list[dict]:
    """Read _inheritance.txt into list of dicts."""
    inh_file = snapshot_path / "_inheritance.txt"
    if not inh_file.exists():
        return []
    entries = []
    for line in inh_file.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or not line.strip():
            continue
        parts = line.split("\t")
        if len(parts) >= 4:
            entries.append({
                "child": parts[0],
                "rel": parts[1],
                "parent": parts[2],
                "file": parts[3],
            })
    return entries


def read_imports(snapshot_path: Path) -> list[dict]:
    """Read _imports.txt into list of dicts."""
    imp_file = snapshot_path / "_imports.txt"
    if not imp_file.exists():
        return []
    entries = []
    for line in imp_file.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or not line.strip():
            continue
        parts = line.split("\t")
        if len(parts) >= 3:
            entries.append({
                "file": parts[0],
                "module": parts[1],
                "names": parts[2],
            })
    return entries


def read_patterns(snapshot_path: Path) -> list[dict]:
    """Read _patterns.txt into list of dicts."""
    pat_file = snapshot_path / "_patterns.txt"
    if not pat_file.exists():
        return []
    entries = []
    for line in pat_file.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or not line.strip():
            continue
        parts = line.split("\t")
        if len(parts) >= 5:
            entries.append({
                "pattern": parts[0],
                "confidence": parts[1],
                "symbol": parts[2],
                "file": parts[3],
                "evidence": parts[4],
            })
    return entries


def _sanitize_id(name: str) -> str:
    """Sanitize a name for use as an entity ID."""
    return name.replace("-", "_").replace(".", "_").replace("/", "_").replace(" ", "_")


# --- Builders ---

class ClassDiagramBuilder:
    """Build a class diagram model from _index.txt + _inheritance.txt."""

    def build(self, snapshot_path: Path) -> Optional[DiagramModel]:
        """Read index files and produce a class diagram DiagramModel."""
        index = read_index(snapshot_path)
        inheritance = read_inheritance(snapshot_path)

        if not index:
            return None

        model = DiagramModel(
            diagram_type="class",
            title="Class Diagram",
        )

        # Group symbols by class
        classes: dict[str, list[dict]] = {}
        for entry in index:
            if entry["kind"] == "class":
                classes.setdefault(entry["name"], [])
            elif entry["scope"] != "-" and entry["scope"] in classes:
                classes.setdefault(entry["scope"], []).append(entry)

        # Create class entities with members as properties
        for class_name, members in sorted(classes.items()):
            entity_id = _sanitize_id(class_name)
            member_list = []
            for m in members:
                sig = m.get("signature", "-")
                if sig == "-":
                    sig = ""
                member_list.append({
                    "name": m["name"],
                    "kind": m["kind"],
                    "signature": sig,
                })
            model.entities.append(DiagramEntity(
                id=entity_id,
                name=class_name,
                entity_type="class",
                properties={"members": member_list},
            ))

        # Create inheritance relationships
        for rel in inheritance:
            parent_id = _sanitize_id(rel["parent"])
            child_id = _sanitize_id(rel["child"])
            model.relationships.append(DiagramRelationship(
                source_id=parent_id,
                target_id=child_id,
                rel_type=rel["rel"],
            ))

        return model if model.entities else None


class InheritanceTreeBuilder:
    """Build an inheritance tree model from _inheritance.txt."""

    def build(self, snapshot_path: Path) -> Optional[DiagramModel]:
        """Read inheritance file and produce a tree DiagramModel."""
        inheritance = read_inheritance(snapshot_path)

        if not inheritance:
            return None

        model = DiagramModel(
            diagram_type="inheritance",
            title="Inheritance Tree",
        )

        # Collect unique node names
        seen_nodes = set()
        for rel in inheritance:
            parent_id = _sanitize_id(rel["parent"])
            child_id = _sanitize_id(rel["child"])

            if parent_id not in seen_nodes:
                model.entities.append(DiagramEntity(
                    id=parent_id, name=rel["parent"], entity_type="class",
                ))
                seen_nodes.add(parent_id)

            if child_id not in seen_nodes:
                model.entities.append(DiagramEntity(
                    id=child_id, name=rel["child"], entity_type="class",
                ))
                seen_nodes.add(child_id)

            model.relationships.append(DiagramRelationship(
                source_id=parent_id,
                target_id=child_id,
                rel_type=rel["rel"],
            ))

        return model if model.entities else None


class DependencyGraphBuilder:
    """Build a module dependency graph from _imports.txt."""

    def build(self, snapshot_path: Path) -> Optional[DiagramModel]:
        """Read imports file and produce a dependency graph DiagramModel."""
        imports = read_imports(snapshot_path)

        if not imports:
            return None

        model = DiagramModel(
            diagram_type="dependency",
            title="Dependency Graph",
        )

        seen_nodes = set()
        seen_edges = set()

        for imp in imports:
            source_id = _sanitize_id(imp["file"].replace("/", "_").replace(".", "_"))
            target_id = _sanitize_id(imp["module"].replace(".", "_"))
            source_label = imp["file"].split("/")[-1] if "/" in imp["file"] else imp["file"]
            target_label = imp["module"].split(".")[-1] if "." in imp["module"] else imp["module"]

            if source_id not in seen_nodes:
                model.entities.append(DiagramEntity(
                    id=source_id, name=source_label, entity_type="module",
                ))
                seen_nodes.add(source_id)

            if target_id not in seen_nodes:
                model.entities.append(DiagramEntity(
                    id=target_id, name=target_label, entity_type="module",
                ))
                seen_nodes.add(target_id)

            edge_key = f"{source_id}->{target_id}"
            if edge_key not in seen_edges:
                model.relationships.append(DiagramRelationship(
                    source_id=source_id,
                    target_id=target_id,
                    rel_type="imports",
                ))
                seen_edges.add(edge_key)

        return model if model.entities else None


class ComponentDiagramBuilder:
    """Build a component diagram from _imports.txt grouped by directory."""

    def build(self, snapshot_path: Path) -> Optional[DiagramModel]:
        """Read imports file, group by directory, produce component DiagramModel."""
        imports = read_imports(snapshot_path)

        if not imports:
            return None

        # Group files by directory
        dir_deps: dict[str, set[str]] = {}
        for imp in imports:
            file_dir = "/".join(imp["file"].split("/")[:-1]) or "root"
            mod_parts = imp["module"].replace(".", "/")
            target_dir = "/".join(mod_parts.split("/")[:-1]) or "root"
            if file_dir != target_dir:
                dir_deps.setdefault(file_dir, set()).add(target_dir)

        if not dir_deps:
            return None

        model = DiagramModel(
            diagram_type="component",
            title="Component Diagram",
        )

        seen_nodes = set()
        seen_edges = set()

        for source_dir, targets in sorted(dir_deps.items()):
            source_id = _sanitize_id(source_dir.replace("/", "_"))
            if source_id not in seen_nodes:
                model.entities.append(DiagramEntity(
                    id=source_id, name=source_dir, entity_type="component",
                ))
                seen_nodes.add(source_id)

            for target_dir in sorted(targets):
                target_id = _sanitize_id(target_dir.replace("/", "_"))
                if target_id not in seen_nodes:
                    model.entities.append(DiagramEntity(
                        id=target_id, name=target_dir, entity_type="component",
                    ))
                    seen_nodes.add(target_id)

                edge_key = f"{source_id}->{target_id}"
                if edge_key not in seen_edges:
                    model.relationships.append(DiagramRelationship(
                        source_id=source_id,
                        target_id=target_id,
                        rel_type="depends_on",
                    ))
                    seen_edges.add(edge_key)

        return model if model.entities else None


class PatternMapBuilder:
    """Build a pattern map from _patterns.txt + _index.txt."""

    def build(self, snapshot_path: Path) -> Optional[DiagramModel]:
        """Read patterns file and produce a pattern map DiagramModel."""
        patterns = read_patterns(snapshot_path)

        if not patterns:
            return None

        model = DiagramModel(
            diagram_type="pattern_map",
            title="Pattern Map",
        )

        # Group by pattern type
        by_type: dict[str, list[dict]] = {}
        for p in patterns:
            by_type.setdefault(p["pattern"], []).append(p)

        for pattern_type, instances in sorted(by_type.items()):
            type_id = _sanitize_id(f"pattern_{pattern_type}")
            model.entities.append(DiagramEntity(
                id=type_id,
                name=pattern_type,
                entity_type="pattern",
            ))

            for inst in instances:
                inst_id = _sanitize_id(f"inst_{inst['symbol']}")
                model.entities.append(DiagramEntity(
                    id=inst_id,
                    name=inst["symbol"],
                    entity_type="instance",
                    parent_id=type_id,
                    properties={"confidence": inst["confidence"], "file": inst["file"]},
                ))
                model.relationships.append(DiagramRelationship(
                    source_id=type_id,
                    target_id=inst_id,
                    rel_type="has_instance",
                ))

        return model if model.entities else None

"""Mermaid serialiser — converts DiagramModel to Mermaid syntax.

Produces .mmd source files that render in markdown viewers, GitHub,
VS Code, and the Mermaid Live Editor.
"""
import logging

from src.ast.diagram_model import DiagramModel

logger = logging.getLogger(__name__)


class MermaidSerialiser:
    """Convert DiagramModel to Mermaid syntax string."""

    def serialise(self, model: DiagramModel) -> str:
        """Convert a DiagramModel to Mermaid syntax.

        Dispatches to the appropriate format method based on diagram_type.
        Returns empty string if model is None or has no entities.
        """
        if model is None or not model.entities:
            return ""

        if model.diagram_type == "class":
            return self._serialise_class_diagram(model)
        elif model.diagram_type == "inheritance":
            return self._serialise_graph(model, direction="TD")
        elif model.diagram_type == "dependency":
            return self._serialise_graph(model, direction="LR")
        elif model.diagram_type == "component":
            return self._serialise_graph(model, direction="LR")
        elif model.diagram_type == "pattern_map":
            return self._serialise_pattern_map(model)
        else:
            logger.warning(f"Unknown diagram type: {model.diagram_type}")
            return ""

    def _serialise_class_diagram(self, model: DiagramModel) -> str:
        """Produce classDiagram syntax with members, visibility, inheritance."""
        lines = ["classDiagram"]

        # Emit class definitions
        for entity in model.entities:
            if entity.entity_type != "class":
                continue
            lines.append(f"    class {sanitize_id(entity.name)} {{")
            members = entity.properties.get("members", [])
            for m in members:
                vis = mermaid_visibility(m.get("name", ""))
                sig = m.get("signature", "")
                if m["kind"] == "method":
                    lines.append(f"        {vis}{m['name']}{sig}")
                elif m["kind"] in ("property", "variable", "constant"):
                    lines.append(f"        {vis}{m['name']}")
            lines.append("    }")

        # Emit relationships
        for rel in model.relationships:
            parent_id = sanitize_id(rel.source_id)
            child_id = sanitize_id(rel.target_id)
            if rel.rel_type == "extends":
                lines.append(f"    {parent_id} <|-- {child_id}")
            elif rel.rel_type == "implements":
                lines.append(f"    {parent_id} <|.. {child_id}")

        if len(lines) > 1:
            return "\n".join(lines)
        return ""

    def _serialise_graph(self, model: DiagramModel, direction: str = "TD") -> str:
        """Produce graph TD/LR syntax for trees, dependencies, components."""
        lines = [f"graph {direction}"]

        seen_edges = set()
        for rel in model.relationships:
            source = sanitize_id(rel.source_id)
            target = sanitize_id(rel.target_id)
            edge_key = f"{source}->{target}"
            if edge_key not in seen_edges:
                # Find entity names for labels
                source_name = self._find_entity_name(model, rel.source_id)
                target_name = self._find_entity_name(model, rel.target_id)
                lines.append(f"    {source}[\"{source_name}\"] --> {target}[\"{target_name}\"]")
                seen_edges.add(edge_key)

        if len(lines) > 1:
            return "\n".join(lines)
        return ""

    def _serialise_pattern_map(self, model: DiagramModel) -> str:
        """Produce pattern map with stadium-shaped pattern type nodes."""
        lines = ["graph TD"]

        for rel in model.relationships:
            source = sanitize_id(rel.source_id)
            target = sanitize_id(rel.target_id)
            source_name = self._find_entity_name(model, rel.source_id)
            target_name = self._find_entity_name(model, rel.target_id)
            lines.append(f"    {source}[(\"{source_name}\")] --> {target}[\"{target_name}\"]")

        if len(lines) > 1:
            return "\n".join(lines)
        return ""

    def _find_entity_name(self, model: DiagramModel, entity_id: str) -> str:
        """Look up entity name by ID."""
        for entity in model.entities:
            if entity.id == entity_id:
                return entity.name
        return entity_id


def sanitize_id(name: str) -> str:
    """Sanitize a name for use as a Mermaid node ID."""
    return name.replace("-", "_").replace(".", "_").replace("/", "_").replace(" ", "_")


def mermaid_visibility(name: str) -> str:
    """Return Mermaid visibility prefix based on naming convention."""
    if name.startswith("__"):
        return "-"  # private
    elif name.startswith("_"):
        return "#"  # protected
    return "+"  # public

"""PlantUML serialiser — converts DiagramModel to PlantUML syntax.

Produces .puml source files renderable by PlantUML server, IDE plugins,
or the PlantUML CLI (plantuml.jar).
"""
import logging

from src.ast.diagram_model import DiagramModel, DiagramEntity

logger = logging.getLogger(__name__)


class PlantUMLSerialiser:
    """Convert DiagramModel to PlantUML syntax string."""

    def serialise(self, model: DiagramModel) -> str:
        """Convert a DiagramModel to PlantUML syntax.

        Dispatches to the appropriate format method based on diagram_type.
        Returns empty string if model is None or has no entities.
        """
        if model is None or not model.entities:
            return ""

        if model.diagram_type == "class":
            return self._serialise_class_diagram(model)
        elif model.diagram_type == "inheritance":
            return self._serialise_inheritance(model)
        elif model.diagram_type == "dependency":
            return self._serialise_graph(model)
        elif model.diagram_type == "component":
            return self._serialise_graph(model)
        elif model.diagram_type == "package":
            return self._serialise_graph(model)
        elif model.diagram_type == "pattern_map":
            return self._serialise_graph(model)
        else:
            logger.warning(f"Unknown diagram type: {model.diagram_type}")
            return ""

    def _serialise_class_diagram(self, model: DiagramModel) -> str:
        """Produce PlantUML class diagram syntax."""
        lines = ["@startuml"]

        if model.title:
            lines.append(f"title {model.title}")
            lines.append("")

        for entity in model.entities:
            if entity.entity_type != "class":
                continue

            stereotype = self._get_stereotype(entity)
            keyword = "abstract class" if "abstract" in entity.properties.get("flags", "") else "class"
            if entity.properties.get("flags", "") == "interface" or entity.entity_type == "interface":
                keyword = "interface"

            lines.append(f"{keyword} {_sanitize_id(entity.name)} {stereotype}{{")
            members = entity.properties.get("members", [])
            for m in members:
                vis = _plantuml_visibility(m.get("name", ""))
                sig = m.get("signature", "")
                if m["kind"] == "method":
                    lines.append(f"    {vis}{m['name']}{sig}")
                elif m["kind"] in ("property", "variable", "constant"):
                    lines.append(f"    {vis}{m['name']}")
            lines.append("}")
            lines.append("")

        # Relationships
        for rel in model.relationships:
            parent = _sanitize_id(rel.source_id)
            child = _sanitize_id(rel.target_id)
            if rel.rel_type == "extends":
                lines.append(f"{parent} <|-- {child}")
            elif rel.rel_type == "implements":
                lines.append(f"{parent} <|.. {child}")

        lines.append("")
        lines.append("@enduml")
        return "\n".join(lines)

    def _serialise_inheritance(self, model: DiagramModel) -> str:
        """Produce PlantUML inheritance diagram."""
        lines = ["@startuml"]

        if model.title:
            lines.append(f"title {model.title}")
            lines.append("")

        # Declare entities
        for entity in model.entities:
            lines.append(f"class {_sanitize_id(entity.name)}")

        lines.append("")

        # Relationships
        for rel in model.relationships:
            parent = _sanitize_id(rel.source_id)
            child = _sanitize_id(rel.target_id)
            if rel.rel_type == "implements":
                lines.append(f"{parent} <|.. {child}")
            else:
                lines.append(f"{parent} <|-- {child}")

        lines.append("")
        lines.append("@enduml")
        return "\n".join(lines)

    def _serialise_graph(self, model: DiagramModel) -> str:
        """Produce PlantUML component/dependency/pattern diagram."""
        lines = ["@startuml"]

        if model.title:
            lines.append(f"title {model.title}")
            lines.append("")

        seen_edges = set()
        for rel in model.relationships:
            source = _sanitize_id(rel.source_id)
            target = _sanitize_id(rel.target_id)
            edge_key = f"{source}->{target}"
            if edge_key not in seen_edges:
                source_name = self._find_entity_name(model, rel.source_id)
                target_name = self._find_entity_name(model, rel.target_id)
                lines.append(f'[{source_name}] --> [{target_name}]')
                seen_edges.add(edge_key)

        lines.append("")
        lines.append("@enduml")
        return "\n".join(lines)

    def _get_stereotype(self, entity: DiagramEntity) -> str:
        """Return PlantUML stereotype string if applicable."""
        flags = entity.properties.get("flags", "")
        if "abstract" in flags:
            return "<<abstract>> "
        if "interface" in flags:
            return "<<interface>> "
        return ""

    def _find_entity_name(self, model: DiagramModel, entity_id: str) -> str:
        """Look up entity name by ID."""
        for entity in model.entities:
            if entity.id == entity_id:
                return entity.name
        return entity_id


def _sanitize_id(name: str) -> str:
    """Sanitize a name for use as a PlantUML identifier."""
    return name.replace("-", "_").replace(".", "_").replace("/", "_").replace(" ", "_")


def _plantuml_visibility(name: str) -> str:
    """Return PlantUML visibility prefix based on naming convention."""
    if name.startswith("__"):
        return "-"  # private
    elif name.startswith("_"):
        return "#"  # protected
    return "+"  # public

"""Graphviz (DOT) serialiser — converts DiagramModel to DOT syntax.

Produces .dot source files renderable by Graphviz CLI (dot, neato, fdp),
VS Code Graphviz extensions, and online viewers.
"""
import logging

from src.ast.diagram_model import DiagramModel, DiagramEntity

logger = logging.getLogger(__name__)

# Node shape based on entity type
_SHAPE_MAP = {
    "class": "record",
    "interface": "ellipse",
    "module": "box",
    "package": "box3d",
    "pattern": "hexagon",
    "instance": "box",
}


class GraphvizSerialiser:
    """Convert DiagramModel to Graphviz DOT syntax string."""

    def serialise(self, model: DiagramModel) -> str:
        """Convert a DiagramModel to DOT syntax.

        Dispatches to the appropriate format method based on diagram_type.
        Returns empty string if model is None or has no entities.
        """
        if model is None or not model.entities:
            return ""

        if model.diagram_type == "class":
            return self._serialise_class_diagram(model)
        elif model.diagram_type == "inheritance":
            return self._serialise_graph(model, directed=True)
        elif model.diagram_type == "dependency":
            return self._serialise_graph(model, directed=True)
        elif model.diagram_type == "component":
            return self._serialise_subgraph(model)
        elif model.diagram_type == "package":
            return self._serialise_subgraph(model)
        elif model.diagram_type == "pattern_map":
            return self._serialise_graph(model, directed=True)
        else:
            logger.warning(f"Unknown diagram type: {model.diagram_type}")
            return ""

    def _serialise_class_diagram(self, model: DiagramModel) -> str:
        """Produce DOT record-based class diagram."""
        lines = ["digraph ClassDiagram {"]
        lines.append("    rankdir=TB;")
        lines.append("    node [shape=record, fontsize=10];")
        lines.append("")

        for entity in model.entities:
            if entity.entity_type != "class":
                continue
            node_id = _sanitize_id(entity.name)
            label = self._build_record_label(entity)
            lines.append(f'    {node_id} [label="{label}"];')

        lines.append("")

        for rel in model.relationships:
            source = _sanitize_id(rel.source_id)
            target = _sanitize_id(rel.target_id)
            if rel.rel_type == "extends":
                lines.append(f"    {target} -> {source} [arrowhead=empty];")
            elif rel.rel_type == "implements":
                lines.append(f"    {target} -> {source} [arrowhead=empty, style=dashed];")

        lines.append("}")
        return "\n".join(lines)

    def _serialise_graph(self, model: DiagramModel, directed: bool = True) -> str:
        """Produce digraph or graph for dependencies, inheritance, patterns."""
        keyword = "digraph" if directed else "graph"
        edge_op = "->" if directed else "--"
        title = _sanitize_id(model.title) if model.title else "G"

        lines = [f"{keyword} {title} {{"]
        lines.append("    rankdir=TB;")
        lines.append("")

        # Declare nodes
        for entity in model.entities:
            node_id = _sanitize_id(entity.id)
            shape = _SHAPE_MAP.get(entity.entity_type, "box")
            lines.append(f'    {node_id} [label="{entity.name}", shape={shape}];')

        lines.append("")

        # Edges
        seen_edges = set()
        for rel in model.relationships:
            source = _sanitize_id(rel.source_id)
            target = _sanitize_id(rel.target_id)
            edge_key = f"{source}{edge_op}{target}"
            if edge_key not in seen_edges:
                label_attr = f', label="{rel.label}"' if rel.label else ""
                lines.append(f"    {source} {edge_op} {target} [{label_attr}];".replace("[ ];", ";").replace("[, ", "["))
                seen_edges.add(edge_key)

        lines.append("}")
        return "\n".join(lines)

    def _serialise_subgraph(self, model: DiagramModel) -> str:
        """Produce DOT with cluster subgraphs for component diagrams."""
        lines = ["digraph Components {"]
        lines.append("    rankdir=LR;")
        lines.append("    compound=true;")
        lines.append("")

        # Group entities by parent_id for clustering
        clusters: dict[str, list[DiagramEntity]] = {}
        standalone: list[DiagramEntity] = []
        for entity in model.entities:
            if entity.parent_id:
                clusters.setdefault(entity.parent_id, []).append(entity)
            else:
                standalone.append(entity)

        # If no parent_id grouping, try grouping by first path segment of name
        if not clusters and standalone:
            for entity in standalone:
                parts = entity.name.replace("\\", "/").split("/")
                if len(parts) > 1:
                    group = parts[0]
                    clusters.setdefault(group, []).append(entity)
                else:
                    clusters.setdefault("_root", []).append(entity)
            standalone = []

        cluster_idx = 0
        for group_name, entities in clusters.items():
            lines.append(f"    subgraph cluster_{cluster_idx} {{")
            lines.append(f'        label="{group_name}";')
            for entity in entities:
                node_id = _sanitize_id(entity.id)
                shape = _SHAPE_MAP.get(entity.entity_type, "box")
                lines.append(f'        {node_id} [label="{entity.name}", shape={shape}];')
            lines.append("    }")
            lines.append("")
            cluster_idx += 1

        for entity in standalone:
            node_id = _sanitize_id(entity.id)
            shape = _SHAPE_MAP.get(entity.entity_type, "box")
            lines.append(f'    {node_id} [label="{entity.name}", shape={shape}];')

        lines.append("")

        # Edges
        for rel in model.relationships:
            source = _sanitize_id(rel.source_id)
            target = _sanitize_id(rel.target_id)
            lines.append(f"    {source} -> {target};")

        lines.append("}")
        return "\n".join(lines)

    def _build_record_label(self, entity: DiagramEntity) -> str:
        """Build DOT record label with class name + members."""
        name = entity.name
        members = entity.properties.get("members", [])

        fields = []
        methods = []
        for m in members:
            vis = _dot_visibility(m.get("name", ""))
            if m["kind"] == "method":
                sig = m.get("signature", "()")
                methods.append(f"{vis} {m['name']}{sig}")
            elif m["kind"] in ("property", "variable", "constant"):
                fields.append(f"{vis} {m['name']}")

        sections = [name]
        if fields:
            sections.append("\\l".join(fields) + "\\l")
        else:
            sections.append("")
        if methods:
            sections.append("\\l".join(methods) + "\\l")
        else:
            sections.append("")

        return "{" + "|".join(sections) + "}"


def _sanitize_id(name: str) -> str:
    """Sanitize a name for use as a DOT node ID."""
    sanitized = name.replace("-", "_").replace(".", "_").replace("/", "_").replace(" ", "_")
    # DOT IDs can't start with a digit
    if sanitized and sanitized[0].isdigit():
        sanitized = "n_" + sanitized
    return sanitized


def _dot_visibility(name: str) -> str:
    """Return DOT/UML visibility prefix based on naming convention."""
    if name.startswith("__"):
        return "-"
    elif name.startswith("_"):
        return "#"
    return "+"

