Enriches ctags output with call hierarchies via Language Server Protocol.
Manages per-language LSP server lifecycle: spin up → query → shutdown.
"""
import logging
import os
import shutil
import subprocess
from pathlib import Path
from typing import Optional

import yaml

from src.ast.models import StructuralAnalysis, SymbolInfo, SymbolKind, CallInfo
from src.ast.provider import AnalysisProvider
from src.ast.lsp_server_manager import LSPServerManager, LSPServerError, LSPTimeoutError

logger = logging.getLogger(__name__)

# Map file extensions to language keys in lsp_servers.yaml
EXTENSION_TO_LANGUAGE = {
    ".py": "python",
    ".pyi": "python",
    ".ts": "typescript",
    ".tsx": "typescript",
    ".js": "typescript",
    ".jsx": "typescript",
    ".go": "go",
    ".rs": "rust",
    ".c": "cpp",
    ".cpp": "cpp",
    ".cc": "cpp",
    ".h": "cpp",
    ".hpp": "cpp",
    ".java": "java",
    ".cs": "csharp",
    ".rb": "ruby",
    ".php": "php",
    ".kt": "kotlin",
    ".kts": "kotlin",
    ".swift": "swift",
    ".lua": "lua",
    ".ex": "elixir",
    ".exs": "elixir",
}

# LSP SymbolKind enum → our canonical SymbolKind
_LSP_SYMBOL_KIND_MAP = {
    1: SymbolKind.MODULE,      # File
    2: SymbolKind.MODULE,      # Module
    3: SymbolKind.MODULE,      # Namespace
    4: SymbolKind.MODULE,      # Package
    5: SymbolKind.CLASS,       # Class
    6: SymbolKind.METHOD,      # Method
    7: SymbolKind.PROPERTY,    # Property
    8: SymbolKind.VARIABLE,    # Field
    9: SymbolKind.FUNCTION,    # Constructor
    10: SymbolKind.INTERFACE,  # Enum
    11: SymbolKind.INTERFACE,  # Interface
    12: SymbolKind.FUNCTION,   # Function
    13: SymbolKind.VARIABLE,   # Variable
    14: SymbolKind.CONSTANT,   # Constant
    22: SymbolKind.VARIABLE,   # Struct → treat as class
    23: SymbolKind.VARIABLE,   # Event
    24: SymbolKind.METHOD,     # Operator
    25: SymbolKind.VARIABLE,   # TypeParameter
}


def detect_language(file_path: str) -> Optional[str]:
    """Detect language from file extension."""
    ext = Path(file_path).suffix.lower()
    return EXTENSION_TO_LANGUAGE.get(ext)


class LSPProvider(AnalysisProvider):
    """Structural analysis via Language Server Protocol.

    Manages per-language LSP server lifecycle. Spins up a server
    for each detected language, queries it for all files of that language,
    then shuts it down. Servers are NOT persistent — they exist only
    for the duration of one analysis run.
    """

    def __init__(self, config_path: Optional[str] = None):
        self._server_configs = self._load_config(config_path)
        self._auto_install = os.environ.get(
            "AST_LSP_AUTO_INSTALL", "true"
        ).lower() == "true"

    def _load_config(self, config_path: Optional[str]) -> dict:
        """Load LSP server configurations."""
        if config_path and os.path.exists(config_path):
            with open(config_path) as f:
                raw = yaml.safe_load(f) or {}
            return raw.get("servers", {})
        return {}

    @property
    def name(self) -> str:
        return "lsp"

    def is_available(self) -> bool:
        """True if at least one LSP server is configured and available/installable."""
        for lang, config in self._server_configs.items():
            command = config.get("command", [])
            if command and shutil.which(command[0]):
                return True
            if config.get("auto_install") and config.get("install_command"):
                return True
        return bool(self._server_configs)

    def analyze_batch(self, file_paths: list[str]) -> dict[str, StructuralAnalysis]:
        """Analyze files by grouping by language, starting servers, querying.

        Returns dict of file_path → StructuralAnalysis with calls populated.
        Only populates call data — symbols/inheritance come from ctags.
        """
        if not file_paths:
            return {}

        # Group files by language
        by_language: dict[str, list[str]] = {}
        for fp in file_paths:
            lang = detect_language(fp)
            if lang and lang in self._server_configs:
                by_language.setdefault(lang, []).append(fp)

        if not by_language:
            return {}

        results: dict[str, StructuralAnalysis] = {}

        for language, lang_files in by_language.items():
            server_config = self._server_configs[language]
            lang_results = self._analyze_language_group(
                language, server_config, lang_files
            )
            results.update(lang_results)

        if results:
            logger.info(f"LSP analysis: {len(results)} files, "
                        f"{sum(len(a.calls) for a in results.values())} call edges")

        return results

    def _analyze_language_group(
        self, language: str, config: dict, file_paths: list[str]
    ) -> dict[str, StructuralAnalysis]:
        """Analyze all files of one language using a single LSP server."""
        # Ensure server binary is available
        command = config.get("command", [])
        if not command:
            return {}

        binary = command[0]
        if not shutil.which(binary):
            if not self._try_auto_install(config):
                logger.info(f"LSP server {binary} not available for {language}, skipping")
                return {}

        # Determine project root (common parent of all files)
        project_root = self._find_project_root(file_paths)

        manager = LSPServerManager({
            **config,
            "timeout_per_file": config.get("timeout_per_file", 30),
        })

        try:
            if not manager.start(project_root):
                return {}

            init_result = manager.initialize(project_root)
            supports_calls = manager.supports_call_hierarchy

            results: dict[str, StructuralAnalysis] = {}

            for file_path in file_paths:
                try:
                    analysis = self._analyze_single_file(
                        manager, file_path, language, supports_calls
                    )
                    if analysis:
                        results[file_path] = analysis
                except LSPTimeoutError:
                    logger.warning(f"LSP timeout for {file_path}, skipping")
                except LSPServerError as e:
                    logger.warning(f"LSP error for {file_path}: {e}")
                except Exception as e:
                    logger.error(f"Unexpected error analyzing {file_path}: {e}")

            return results

        except Exception as e:
            logger.error(f"LSP server failed for {language}: {e}")
            return {}
        finally:
            manager.shutdown()

    def _analyze_single_file(
        self, manager: LSPServerManager, file_path: str,
        language: str, supports_calls: bool
    ) -> Optional[StructuralAnalysis]:
        """Analyze a single file via LSP, extracting call graph."""
        try:
            content = Path(file_path).read_text(encoding="utf-8")
        except Exception:
            return None

        language_id = self._get_language_id(language)
        manager.open_file(file_path, content, language_id)

        calls: list[CallInfo] = []

        try:
            if supports_calls:
                # Get document symbols to find functions/methods
                symbols = manager.get_document_symbols(file_path)
                callable_symbols = self._extract_callable_symbols(symbols)

                for sym_name, sym_kind, line, character in callable_symbols:
                    try:
                        items = manager.get_call_hierarchy_items(
                            file_path, line, character
                        )
                        if not items:
                            continue

                        for item in items:
                            outgoing = manager.get_outgoing_calls(item)
                            for call in outgoing:
                                call_info = self._map_outgoing_call(
                                    call, file_path, sym_name
                                )
                                if call_info:
                                    calls.append(call_info)
                    except (LSPTimeoutError, LSPServerError):
                        continue

            return StructuralAnalysis(
                file_path=file_path,
                language=language,
                calls=calls,
                provider_used="lsp",
                analysis_depth="rich",
            )
        finally:
            try:
                manager.close_file(file_path)
            except Exception:
                pass

    def _extract_callable_symbols(self, symbols: list) -> list[tuple]:
        """Extract function/method symbols from documentSymbol response.

        Returns list of (qualified_name, kind, line, character) tuples.
        """
        result = []
        self._walk_symbols(symbols, None, result)
        return result

    def _walk_symbols(self, symbols: list, parent_name: Optional[str], result: list):
        """Recursively walk symbol tree extracting callable symbols."""
        for sym in symbols:
            kind = sym.get("kind", 0)
            name = sym.get("name", "")
            range_info = sym.get("selectionRange") or sym.get("range", {})
            start = range_info.get("start", {})
            line = start.get("line", 0)
            character = start.get("character", 0)

            qualified_name = f"{parent_name}.{name}" if parent_name else name

            # Functions (12), Methods (6), Constructors (9)
            if kind in (6, 9, 12):
                result.append((qualified_name, kind, line, character))

            # Recurse into children (class methods, etc.)
            children = sym.get("children", [])
            if children:
                # For classes, use class name as parent
                child_parent = name if kind == 5 else parent_name
                self._walk_symbols(children, child_parent, result)

    def _map_outgoing_call(
        self, call: dict, caller_file: str, caller_name: str
    ) -> Optional[CallInfo]:
        """Map an LSP outgoing call to our CallInfo model."""
        to = call.get("to") or call.get("callee")
        if not to:
            return None

        callee_name = to.get("name", "")
        if not callee_name:
            return None

        # Extract callee file from URI
        callee_uri = to.get("uri", "")
        callee_file = self._uri_to_path(callee_uri) if callee_uri else "-"

        # Get call site line
        from_ranges = call.get("fromRanges", [])
        line = 0
        if from_ranges:
            line = from_ranges[0].get("start", {}).get("line", 0)

        # Build qualified callee name
        # If callee has a containerName, use it
        container = to.get("detail", "") or to.get("containerName", "")
        if container:
            callee_qualified = f"{container}.{callee_name}"
        else:
            callee_qualified = callee_name

        return CallInfo(
            caller_file=caller_file,
            caller_name=caller_name,
            callee_file=callee_file,
            callee_name=callee_qualified,
            line=line,
        )

    def _try_auto_install(self, config: dict) -> bool:
        """Attempt to auto-install the LSP server."""
        if not config.get("auto_install", True) or not self._auto_install:
            return False

        install_cmd = config.get("install_command")
        if not install_cmd:
            return False

        # Check if package manager is available
        pkg_mgr = config.get("package_manager")
        if pkg_mgr and not shutil.which(pkg_mgr):
            logger.info(f"Package manager '{pkg_mgr}' not available, skipping auto-install")
            return False

        try:
            logger.info(f"Auto-installing LSP server: {install_cmd}")
            result = subprocess.run(
                install_cmd, shell=True,
                capture_output=True, text=True, timeout=120,
            )
            if result.returncode == 0:
                logger.info("LSP server installed successfully")
                return True
            else:
                logger.warning(f"LSP server install failed: {result.stderr[:200]}")
                return False
        except Exception as e:
            logger.warning(f"LSP server install error: {e}")
            return False

    def _find_project_root(self, file_paths: list[str]) -> str:
        """Find common parent directory of all files."""
        if not file_paths:
            return "."
        paths = [Path(fp).resolve().parent for fp in file_paths]
        # Find common prefix
        common = paths[0]
        for p in paths[1:]:
            while not str(p).startswith(str(common)):
                common = common.parent
                if common == common.parent:
                    return "."
        return str(common)

    def _get_language_id(self, language: str) -> str:
        """Map our language key to LSP languageId."""
        mapping = {
            "python": "python",
            "typescript": "typescript",
            "go": "go",
            "rust": "rust",
            "cpp": "cpp",
            "java": "java",
            "csharp": "csharp",
            "ruby": "ruby",
            "php": "php",
            "kotlin": "kotlin",
            "swift": "swift",
            "lua": "lua",
            "elixir": "elixir",
        }
        return mapping.get(language, language)

    def _uri_to_path(self, uri: str) -> str:
        """Convert file:// URI to file path."""
        if uri.startswith("file:///"):
            path = uri[8:]  # Remove file:///
        elif uri.startswith("file://"):
            path = uri[7:]
        else:
            return "-"

        # URL decode
        import urllib.parse
        path = urllib.parse.unquote(path)

        # Normalize
        path = path.replace("\\", "/")
        return path

