import pytest
from unittest.mock import MagicMock, patch
from pathlib import Path

from src.ast.lsp_provider import LSPProvider, detect_language, EXTENSION_TO_LANGUAGE
from src.ast.models import StructuralAnalysis, CallInfo


class TestLanguageDetection:
    """Test file extension → language mapping."""

    def test_python_detected(self):
        assert detect_language("src/api.py") == "python"
        assert detect_language("types.pyi") == "python"

    def test_typescript_detected(self):
        assert detect_language("app.ts") == "typescript"
        assert detect_language("component.tsx") == "typescript"
        assert detect_language("script.js") == "typescript"
        assert detect_language("component.jsx") == "typescript"

    def test_go_detected(self):
        assert detect_language("main.go") == "go"

    def test_rust_detected(self):
        assert detect_language("lib.rs") == "rust"

    def test_unknown_returns_none(self):
        assert detect_language("README.md") is None
        assert detect_language("Makefile") is None
        assert detect_language("data.csv") is None

    def test_all_extensions_mapped(self):
        """Every extension in EXTENSION_TO_LANGUAGE maps to a valid language."""
        for ext, lang in EXTENSION_TO_LANGUAGE.items():
            assert ext.startswith(".")
            assert isinstance(lang, str)
            assert len(lang) > 0


class TestLSPProviderInit:
    """Test LSPProvider initialization."""

    def test_name_is_lsp(self):
        provider = LSPProvider()
        assert provider.name == "lsp"

    def test_empty_config_no_crash(self):
        provider = LSPProvider(config_path="/nonexistent/path.yaml")
        assert provider._server_configs == {}

    def test_is_available_false_with_no_config(self):
        provider = LSPProvider()
        # No servers configured, but returns True if config is non-empty
        # With empty config, still returns False
        assert not provider.is_available() or provider._server_configs


class TestAnalyzeBatch:
    """Test LSPProvider.analyze_batch()."""

    def test_groups_files_by_language(self):
        provider = LSPProvider()
        provider._server_configs = {"python": {"command": ["pyright"]}}

        # Mock the analyze method to track what gets called
        with patch.object(provider, "_analyze_language_group", return_value={}) as mock:
            provider.analyze_batch([
                "src/api.py",
                "src/models.py",
                "src/app.ts",  # No typescript config
            ])
            # Should group python files together
            mock.assert_called_once()
            args = mock.call_args
            assert args[0][0] == "python"  # language
            assert len(args[0][2]) == 2  # 2 python files

    def test_skips_languages_with_no_config(self):
        provider = LSPProvider()
        provider._server_configs = {}  # No configs

        result = provider.analyze_batch(["src/api.py", "src/app.ts"])
        assert result == {}

    def test_returns_empty_for_empty_input(self):
        provider = LSPProvider()
        assert provider.analyze_batch([]) == {}

    def test_returns_empty_for_non_code_files(self):
        provider = LSPProvider()
        provider._server_configs = {"python": {"command": ["pyright"]}}
        result = provider.analyze_batch(["README.md", "Makefile", "data.csv"])
        assert result == {}


