        provider = LSPProvider()
        call = {
            "to": {
                "name": "execute",
                "uri": "file:///src/db.py",
                "detail": "Database",
            },
            "fromRanges": [{"start": {"line": 38, "character": 8}}],
        }
        result = provider._map_outgoing_call(call, "src/user.py", "UserService.save")
        assert result is not None
