        provider = LSPProvider()
        symbols = [
            {"name": "main", "kind": 12, "range": {"start": {"line": 0, "character": 0}},
             "selectionRange": {"start": {"line": 0, "character": 4}}},
            {"name": "helper", "kind": 12, "range": {"start": {"line": 10, "character": 0}},
             "selectionRange": {"start": {"line": 10, "character": 4}}},
        ]
        result = provider._extract_callable_symbols(symbols)
        assert len(result) == 2
        names = [r[0] for r in result]
        assert "main" in names
        assert "helper" in names

    def test_extract_methods_from_class(self):
        provider = LSPProvider()
        symbols = [
            {
                "name": "UserService", "kind": 5,
                "range": {"start": {"line": 0}},
                "selectionRange": {"start": {"line": 0, "character": 6}},
                "children": [
                    {"name": "get_user", "kind": 6,
                     "range": {"start": {"line": 5}},
                     "selectionRange": {"start": {"line": 5, "character": 8}}},
                    {"name": "save_user", "kind": 6,
                     "range": {"start": {"line": 15}},
                     "selectionRange": {"start": {"line": 15, "character": 8}}},
                ],
            },
        ]
        result = provider._extract_callable_symbols(symbols)
        assert len(result) == 2
        names = [r[0] for r in result]
        assert "UserService.get_user" in names
        assert "UserService.save_user" in names

    def test_skips_non_callable_symbols(self):
        provider = LSPProvider()
        symbols = [
            {"name": "CONSTANT", "kind": 14, "range": {"start": {"line": 0}},
             "selectionRange": {"start": {"line": 0, "character": 0}}},
            {"name": "variable", "kind": 13, "range": {"start": {"line": 1}},
             "selectionRange": {"start": {"line": 1, "character": 0}}},
        ]
        result = provider._extract_callable_symbols(symbols)
        assert len(result) == 0


class TestUriConversion:
    """Test URI to path conversion."""

    def test_file_uri_to_path(self):
        provider = LSPProvider()
        assert provider._uri_to_path("file:///src/api.py") == "src/api.py"

    def test_empty_uri(self):
        provider = LSPProvider()
        assert provider._uri_to_path("") == "-"

    def test_non_file_uri(self):
        provider = LSPProvider()
        assert provider._uri_to_path("https://example.com") == "-"

